def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = 0
    for o in op:
        if o == 'D':
            opp_def += 1

    if n >= 2 and opp_def == n:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    if n < 4:
        return 'C'

    success = 0
    sucker = 0
    punish = 0
    for m, o in zip(me, op):
        if m == 'D':
            if o == 'C':
                success += 1
            else:
                punish += 1
        else:
            if o == 'D':
                sucker += 1
    bad = sucker + punish

    if me[-1] == 'D' and success == 1 and bad == 0:
        return 'C'

    if n >= 3 and me[-2] == 'D' and me[-1] == 'C':
        if op[-1] == 'C' and opp_def <= max(2, n * 4 // 5):
            return 'D'
        return 'C'

    if opp_def == 0:
        return 'D'

    start = n - 12
    if start < 0:
        start = 0
    recent_success = 0
    recent_bad = 0
    for i in range(start, n):
        if me[i] == 'D' and op[i] == 'C':
            recent_success += 1
        elif op[i] == 'D':
            recent_bad += 1

    if (
        success >= 2
        and success > bad
        and recent_success >= recent_bad
        and opp_def <= max(1, n * 2 // 5)
    ):
        if not (me[-1] == 'D' and op[-1] == 'D' and recent_bad >= 2):
            return 'D'

    if opp_def >= max(2, n * 3 // 5):
        if sucker <= max(1, n // 6) and punish >= sucker and success >= max(1, punish // 2):
            if rng.random() < 0.25 or n % 7 == 0:
                return 'C'
        if n % 11 == 0:
            return 'C'
        return 'D'

    if me[-1] == 'C' and op[-1] == 'D':
        if me[-2] == 'D':
            return 'C'
        if opp_def * 4 <= n and rng.random() < 0.2:
            return 'C'
        return 'D'

    if me[-1] == 'D' and op[-1] == 'D':
        if opp_def * 2 <= n and success >= 1:
            if rng.random() < 0.45 or n % 9 == 0:
                return 'C'
        return 'D'

    remaining = 100 - n
    if remaining <= 2:
        if opp_def == 0:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        if remaining == 1 and opp_def * 2 <= n:
            return 'D'
        return 'C'

    if me[-1] == 'D' and op[-1] == 'C':
        if success > bad and opp_def * 5 <= n * 2:
            return 'D'
        return 'C'

    if me[-1] == 'C' and op[-1] == 'C':
        if opp_def <= max(1, n // 20) and n >= 30 and rng.random() < 0.03:
            if success > bad or bad == 0:
                return 'D'
        return 'C'

    if op[-1] == 'C':
        return 'C'

    if opp_def * 2 <= n and rng.random() < 0.35:
        return 'C'

    if n >= 6:
        recent_def = 0
        for x in op[-6:]:
            if x == 'D':
                recent_def += 1
        if recent_def <= 2 and rng.random() < 0.25:
            return 'C'

    if n % 9 == 0:
        return 'C'

    return 'D'
